package com.classvoice.model;
import java.io.Serializable; import java.time.LocalDateTime;
public class Feedback implements Serializable { private long feedbackId,lectureId,studentId; private Long topicId; private String feedbackText,topicName,lectureTitle; private LocalDateTime submittedAt;
 public long getFeedbackId(){return feedbackId;} public void setFeedbackId(long v){feedbackId=v;} public long getLectureId(){return lectureId;} public void setLectureId(long v){lectureId=v;} public long getStudentId(){return studentId;} public void setStudentId(long v){studentId=v;} public Long getTopicId(){return topicId;} public void setTopicId(Long v){topicId=v;} public String getFeedbackText(){return feedbackText;} public void setFeedbackText(String v){feedbackText=v;} public String getTopicName(){return topicName;} public void setTopicName(String v){topicName=v;} public String getLectureTitle(){return lectureTitle;} public void setLectureTitle(String v){lectureTitle=v;} public LocalDateTime getSubmittedAt(){return submittedAt;} public void setSubmittedAt(LocalDateTime v){submittedAt=v;}}
